CIRCUIT_BREAKER_STATE = Gauge(
    'circuit_breaker_state', 'Current state of the circuit breaker (0=closed, 1=open, 2=half-open)', ['breaker_name']
)

def log_and_metric_exception(logger_obj: logging.Logger, metric_counter: Counter, exception: Exception, message: str, **kwargs):
    """Logs an exception and increments a Prometheus counter."""
    logger_obj.error(f"{message}: {exception}", exc_info=True, **kwargs)
    metric_counter.inc()

def get_breaker_state_value(state: str) -> int:
    """Converts pybreaker state string to an integer for Prometheus Gauge."""
    if state == 'closed':
        return 0
    elif state == 'open':
        return 1
    elif state == 'half-open':
        return 2
    return -1 # Unknown state